{"command":"$ErrorActionPreference='SilentlyContinue'
$p = Get-Process | Where-Object { $_.ProcessName -match 'Telegram' } | Select-Object ProcessName, Id, MainWindowTitle
if ($p) { $p | Format-Table -AutoSize | Out-String } else { "Telegram Desktop НЕ запущен" }
"--- Установка ---"
$paths = @(
  "$env:APPDATA\Telegram Desktop\Telegram.exe",
  "$env:LOCALAPPDATA\Telegram Desktop\Telegram.exe",
  "$env:ProgramFiles\Telegram Desktop\Telegram.exe"
)
$found = $paths | Where-Object { Test-Path $_ }
if ($found) { $found } else { "Telegram.exe не найден в стандартных путях" }","description":"Check if Telegram Desktop is running or installed"}

{"command":"$ErrorActionPreference='SilentlyContinue'
"--- Сессия Telegram (tdata) ---"
$t = "$env:APPDATA\Telegram Desktop\tdata"
if (Test-Path $t) {
  $files = Get-ChildItem $t -File | Select-Object -ExpandProperty Name
  if ($files -contains "key_datas" -or $files -contains "map*") { "Сессия найдена: вход выполнен ранее" }
  elseif ($files) { "tdata есть, но файлы: $($files -join ', ')" }
  else { "tdata пуста — нужен первый вход" }
} else { "tdata нет — нужен первый вход (QR/номер)" }","description":"Check for saved Telegram session"}
